/**
 * Unit tests for MultivariateNormalDistribution#density
 */
public class MultivariateNormalDistribution_density_TriageGen3Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDensityWithValidInput() throws Exception {
        // Setup a 2D Multivariate Normal Distribution
        // Mean = [0, 0], Covariance = [[1, 0], [0, 1]] (Standard Bivariate Normal)
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test at the mean [0, 0]
        // Formula: (2*PI)^(-dim/2) * |det|^(-0.5) * exp(-0.5 * (x-mu)' * inv(Sigma) * (x-mu))
        // dim = 2, |det| = 1, exponent = 0
        // Result: (2*PI)^(-1) * 1 * 1 = 1 / (2 * PI)
        double[] vals = {0.0, 0.0};
        double expected = 1.0 / (2.0 * Math.PI);
        double actual = distribution.density(vals);
        assertEquals("Density at mean should match theoretical value", expected, actual, EPSILON);

        // Test at [1, 1]
        // exponent = -0.5 * ([1, 1] * I * [1, 1]') = -0.5 * (1 + 1) = -1
        // Result: (1 / 2PI) * exp(-1)
        double[] vals2 = {1.0, 1.0};
        double expected2 = (1.0 / (2.0 * Math.PI)) * Math.exp(-1.0);
        double actual2 = distribution.density(vals2);
        assertEquals("Density at [1, 1] should match theoretical value", expected2, actual2, EPSILON);
    }

    @Test
    public void testDensityWithDimensionMismatch() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Dimension is 2, provide 3 elements
        double[] invalidVals = {0.0, 0.0, 0.0};

        assertThrows(DimensionMismatchException.class, () -> {
            distribution.density(invalidVals);
        });
    }

    @Test
    public void testDensityWithDimensionMismatchLow() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Dimension is 2, provide 1 element
        double[] invalidVals = {0.0};

        assertThrows(DimensionMismatchException.class, () -> {
            distribution.density(invalidVals);
        });
    }

    @Test
    public void testDensityOneDimension() throws Exception {
        // 1D case: MultivariateNormal is just Normal distribution
        double[] means = {5.0};
        double[][] covariances = {{4.0}}; // variance = 4, stdDev = 2
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test at mean [5.0]
        // dim = 1, |det| = 4, exponent = 0
        // Result: (2*PI)^(-0.5) * (4)^(-0.5) * 1 = 1 / (sqrt(2*PI) * 2)
        double[] vals = {5.0};
        double expected = 1.0 / (Math.sqrt(2.0 * Math.PI) * 2.0);
        double actual = distribution.density(vals);
        assertEquals("1D density at mean should match theoretical value", expected, actual, EPSILON);
    }
}
